mapper.select:
select su.id, nickname as nickname, mobile as mobile from system_users su left join system_user_dept sud on sud.user_id = su.id where su.deleted = 0 and sud.deleted = 0
and sud.dept_id = #{deptUserOAReqVO.deptId}
and (nickname like concat('%',#{deptUserOAReqVO.nameOrMobile},'%') or mobile like concat('%',#{deptUserOAReqVO.nameOrMobile},'%'))
and sud.type = #{deptUserOAReqVO.type}
group by su.id

